# The "types of ... you'll meet" cards: (title, picture, how to recognise it, pros, cons, use for)
from svg import *
TYPES = [
 ('Active buzzer',S('<path d="M62 50V68M78 50V64" stroke="#cbd5e1" stroke-width="2.5"/><rect x="44" y="14" width="52" height="36" rx="10" fill="#111827"/><circle cx="70" cy="24" r="4" fill="#0b1220"/><rect x="44" y="40" width="52" height="10" fill="#0f172a"/><text x="86" y="30" font-size="12" font-weight="800" fill="#ef4444" font-family="system-ui">+</text>'),'A black cylinder, sealed underneath with black resin. The + leg is longer, and there\'s often a "+" on top or a sticker.',['Beeps on plain DC: no circuit needed','Loud for its size'],['One fixed pitch (~2.3 kHz)','~30 mA: borderline for a pin'],'Alarms, "done" beeps, project 11. Also sold on a small module (GT1143).'),
 ('Passive buzzer',S('<path d="M62 50V68M78 50V68" stroke="#cbd5e1" stroke-width="2.5"/><rect x="44" y="18" width="52" height="32" rx="10" fill="#111827"/><circle cx="70" cy="28" r="4" fill="#0b1220"/><rect x="48" y="44" width="44" height="6" fill="#16a34a"/>'),'Same black cylinder, but you can see a green circuit board underneath, and both legs are the same length.',['Any pitch you like: melodies, sirens','Driven by a 555 or Arduino tone()'],['Silent on DC (just a click)','Needs a square wave'],'Tones and tunes, the 555 buzzer of project 8.'),
 ('Piezo disc',S('<circle cx="70" cy="32" r="26" fill="#b45309"/><circle cx="70" cy="32" r="17" fill="#e5e7eb"/><path d="M70 32L28 66M74 30L112 66" stroke="#ef4444" stroke-width="2"/><path d="M74 30L112 66" stroke="#111" stroke-width="2"/>'),'A brass disc with a white ceramic centre and two thin wires.',['Tiny current: straight from a pin','Also a sensor: knock it and it makes a voltage'],['Quiet without a resonating case','Thin wires break easily'],'Cheap beepers, knock sensors, contact mics for guitars.'),
 ('Speaker 8 Ω',S('<circle cx="70" cy="35" r="30" fill="#1f2937" stroke="#64748b" stroke-width="2"/><circle cx="70" cy="35" r="20" fill="#374151"/><circle cx="70" cy="35" r="8" fill="#111827"/><path d="M100 35h30" stroke="#cbd5e1" stroke-width="2"/>'),'A round cone in a metal frame, with two solder tabs at the back (8 Ω, 0.5 W printed on the magnet).',['Reproduces full music and voice','Robust and cheap'],['Needs an amplifier','Never DC'],'Amps (project 10, your Ruby), sirens (project 17), radios.'),
 ('DC motor (brushed)',S('<rect x="34" y="16" width="64" height="38" rx="16" fill="#94a3b8"/><rect x="26" y="24" width="10" height="22" rx="2" fill="#b45309"/><rect x="98" y="32" width="30" height="6" fill="#cbd5e1"/><path d="M26 30H16M26 40H16" stroke="#cbd5e1" stroke-width="2"/>'),'A small metal can with a shaft at one end and two solder tabs at the other (RE140: 3–9 V, 9,200 rpm).',['Simple: two wires, reverse them to reverse it','Speed follows voltage'],['Brushes wear and make electrical noise','High stall current'],'Fans, toy cars, pumps, projects 23–25.'),
 ('Geared motor / servo',S('<rect x="20" y="20" width="60" height="32" rx="6" fill="#facc15"/><rect x="80" y="24" width="34" height="24" rx="3" fill="#ca8a04"/><rect x="114" y="32" width="18" height="8" fill="#cbd5e1"/>'),'A motor with a gearbox (often yellow for robot kits), or a servo: a geared motor plus position control, with 3 wires.',['Slow but strong','A servo goes to an exact angle'],['Gearbox noise','A servo needs a pulse signal'],'Robot wheels, steering, moving flaps and arms.')
]
